 const bg=BACKGROUNDS.find(x=>x.id===save.background)||BACKGROUNDS[0];$('arena').style.background=bg.color;
 for(const [items,id,owned,key] of [[BALLS,'ball-store','ownedBalls','ball'],[BACKGROUNDS,'background-store','ownedBackgrounds','background'],[TRAILS,'trail-store','ownedTrails','trail'],[EFFECTS,'effect-store','ownedEffects','effect']]){
 $(id).replaceChildren(...items.filter(item=>item.name.toLowerCase().includes($('store-search').value.toLowerCase().trim())).map(item=>{const card=document.createElement('article');card.className='shop-card';const preview=document.createElement('div');preview.className='cosmetic-preview '+(item.shape||'backdrop');preview.style.setProperty('--preview',item.color||'#ffffff');if(id==='ball-store'){preview.classList.add('ball-preview');const c=document.createElement('canvas');c.width=100;c.height=72;paintBall(c.getContext('2d'),50,36,17,item,0);preview.append(c)}if(id==='background-store'&&item.pattern){preview.classList.add('ball-preview');const c=document.createElement('canvas');c.width=180;c.height=72;drawAmbient(c.getContext('2d'),180,72,item,'none',0);preview.append(c)}if(id==='trail-store'||id==='effect-store'){preview.classList.add('ball-preview');const c=document.createElement('canvas');c.width=180;c.height=72;const g=c.getContext('2d');if(id==='trail-store'){const points=Array.from({length:20},(_,i)=>({x:145-i*5,y:36+Math.sin(i*.2)*12,life:.25-i*.01}));paintTrail(g,points,item.id,item.color||'#73e7f4');paintBall(g,145,36,5,BALLS[0],0)}else drawAmbient(g,180,72,BACKGROUNDS[0],item.id,1);preview.append(c)}const name=document.createElement('h4');name.textContent=item.name;const b=document.createElement('button');b.className='shop-button';const has=save[owned].includes(item.id),equipped=save[key]===item.id;b.textContent=equipped?'EQUIPPED':has?'EQUIP':item.price+' STEROIDS';b.disabled=equipped||(!has&&save.steroids<item.price);b.addEventListener('click',()=>{if(state==='playing'||state==='paused')return;if(!save[owned].includes(item.id)){if(save.steroids<item.price)return;save.steroids-=item.price;save[owned].push(item.id)}save[key]=item.id;persist();$('store-message').textContent=item.name+' equipped.';renderV5()});const demo=document.createElement('button');demo.className='preview-button';demo.textContent='PREVIEW';demo.addEventListener('click',()=>{previewChoice={...save,[key]:item.id};$('preview-label').textContent=item.name+' · visual preview';$('store-preview').hidden=false;drawStorePreview()});card.append(preview,name,demo,b);return card}))}
 filterStore();renderHistory();renderTournament();
 $('tournament-summary').textContent=save.tournament?'In progress: round '+save.tournament.round+'/'+save.tournament.total+' · '+save.tournament.difficulty+' · '+save.tournament.earned+' Steroids earned. Resume below.':save.tournamentWins+' tournament stages won.';
 let resume=$('resume-tournament');if(!resume){resume=document.createElement('button');resume.id='resume-tournament';resume.className='primary';resume.textContent='RESUME TOURNAMENT';resume.addEventListener('click',()=>launchRound());$('page-tournament').append(resume)}resume.hidden=!save.tournament;
