function paintTrail(c,points,choice,color){const index=choice==='classic'?-1:Number(choice.split('-')[1]);if(index===0||index===2||index===3){c.save();c.lineWidth=index===2?7:3;c.strokeStyle=color;c.globalAlpha=.22;c.beginPath();points.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.stroke();if(index===3){c.translate(4,4);c.stroke()}c.restore();return}for(let i=0;i<points.length;i++){const p=points[i];c.save();c.globalAlpha=Math.max(0,p.life/.25)*.4;c.fillStyle=index===8?'hsl('+(i*16+(save.reduced?0:performance.now()*.05))%360+' 90% 70%)':color;c.strokeStyle=c.fillStyle;c.lineWidth=1;c.beginPath();if(index===1){polygon(c,p.x,p.y,3,4,0,1);c.fill()}else if(index===4){polygon(c,p.x,p.y,4,3,i);c.fill()}else if(index===5){c.arc(p.x+Math.sin(i)*3,p.y,2+i%3,0,TAU);c.fill()}else if(index===6||index===7){c.arc(p.x,p.y,index===6?4:3+(1-p.life/.25)*9,0,TAU);c.stroke()}else if(index===9){c.arc(p.x,p.y,7,0,TAU);c.stroke()}else{c.arc(p.x,p.y,5,0,TAU);c.fill()}c.restore()}}
