function objectPosition(object){const a=object.angle-Math.PI/2,r=object.wall?(RADII[0]+RADII[1])/2:RADII[object.lane];return{x:Math.cos(a)*r,y:Math.sin(a)*r}}
function burst(object,color,n=14){if(save.reduced)n=Math.min(n,4);const p=objectPosition(object);for(let i=0;i<n&&particles.length<240;i++){const angle=Math.random()*TAU,speed=30+Math.random()*105;particles.push({x:p.x,y:p.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:.3+Math.random()*.35,max:.65,color,size:2+Math.random()*2})}}
function events(){for(const e of engine.drain()){sound.play(e.type);switch(e.type){case'energy':burst(e.object,'#c9ff65',9);pulse=.12;break;case'gold':burst(e.object,'#c9ff65',20);showMessage(`RISK GEM +${fmt(e.amount)}`);pulse=.2;break;case'shield':burst(e.object,'#8cdbef',18);showMessage(`SHIELD RESTORED +${fmt(e.amount)}`);break;case'near':burst(e.object,'#c9ff65',27);showMessage(`CLOSE CALL +${fmt(e.amount)}`);shake=save.reduced?0:3;pulse=.35;if(!save.reduced&&navigator.vibrate)navigator.vibrate(15);break;case'milestone':showMessage(`COMBO ×${e.multiplier}`);pulse=.35;break;case'damage':burst(e.object,'#ff8147',25);showMessage(`${e.shields} SHIELD${e.shields===1?'':'S'} LEFT · COMBO REDUCED`,'damage');shake=save.reduced?0:7;flash=save.reduced?0:.22;if(!save.reduced&&navigator.vibrate)navigator.vibrate([25,20,25]);break;case'objective':showMessage(`OBJECTIVE +500`);break;case'phase':showMessage(e.phase);break;case'end':finish();break}}}
function updateHUD(){if(!engine)return;$('score').textContent=Math.floor(engine.score).toLocaleString('en-US',{minimumIntegerDigits:6});$('shields').textContent=Array.from({length:engine.maxShields},(_,i)=>i<engine.shields?'▰':'▱').join(' ');$('shields').setAttribute('aria-label',`${engine.shields} shields`);renderTournament();if(!engine.recordCelebrated&&state==='playing'&&save.records[engine.difficulty]>0&&engine.score>save.records[engine.difficulty]){engine.recordCelebrated=true;showMessage('NEW PERSONAL BEST');sound.play('record')}const remain=Math.max(0,Math.ceil(((engine.tournament||engine.level)?engine.duration:DURATION)-engine.time));$('timer').textContent=formatTime(engine.tournament?remain:engine.config.survival?engine.time:remain);$('multiplier').textContent=`×${engine.multiplier}`;$('phase').textContent=phaseAt(engine.time,engine.difficulty);$('phase-small').textContent=engine.tournament?'ROUND '+engine.tournament.round+'/'+engine.tournament.total:engine.config.survival?'TIME SURVIVED':engine.time<WARMUP?`WARM UP · ${Math.ceil(WARMUP-engine.time)}s`:phaseAt(engine.time,engine.difficulty);$('seed-label').textContent=`RUN ${String(save.runs+1).padStart(3,'0')}`;$('run-fill').style.width=`${(engine.tournament||engine.level)?engine.time/engine.duration*100:engine.config.survival?0:engine.time/DURATION*100}%`;const index=MULTIPLIERS.indexOf(engine.multiplier);const next=THRESHOLDS[index+1];$('combo-fill').style.width=`${next?(engine.streak-THRESHOLDS[index])/(next-THRESHOLDS[index])*100:100}%`;$('combo-caption').textContent=next?`${Math.max(0,next-engine.streak)} STREAK TO ×${MULTIPLIERS[index+1]}`:'MAXIMUM SIGNAL';if(state==='playing')$('run-status').textContent=engine.tournament?'ROUND '+engine.tournament.round+'/'+engine.tournament.total+' · '+engine.config.label+' · '+formatTime(remain)+' to clear':engine.config.survival?`${engine.config.label.toUpperCase()} · ${formatTime(engine.time)} survived · one shield, no recovery`:engine.time<WARMUP?`Warm-up: ${Math.ceil(WARMUP-engine.time)}s left. Space or tap switches tracks.`:engine.difficulty==='hard'?'HARD: Extreme speed. Read the next barrier and commit.':engine.time<90?'Warm-up complete. Stay clean and build your combo.':engine.time<110?'Overdrive. Keep your eyes one barrier ahead.':'Final rush. Make this orbit count.';if(engine.config.impossible&&!engine.tournament)$('countdown-call').textContent=engine.time%20>=18.5?'COLLAPSE · BOTH ORBITS':'';if((engine.tournament||!engine.config.survival)&&remain<=10&&remain!==lastCountdown&&state==='playing'){lastCountdown=remain;sound.play('countdown');$('countdown-call').textContent=remain>0?`${remain} SECONDS · SCORE RUSH`:''}if(engine.level){$("phase").textContent="LEVEL "+engine.level;$("phase-small").textContent="1000 LEVEL CAMPAIGN";$("run-status").textContent="LEVEL "+engine.level+" · "+formatTime(remain)+" to clear";$("mode-speed").textContent=engine.levelProfile.speed.toFixed(2)+"×"}renderObjectives()}
function resize(){const b=canvas.getBoundingClientRect();width=b.width;height=b.height;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);scale=Math.min(width/560,height/505);ctx.setTransform(dpr,0,0,dpr,0,0)}
function draw(dt){
 const dpr=Math.min(window.devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,width,height);drawAmbient(ctx,width,height,BACKGROUNDS.find(x=>x.id===save.background)||BACKGROUNDS[0],save.effect,performance.now()/1000);ctx.save();ctx.translate(width/2+(shake?Math.sin(performance.now()*.07)*shake:0),height/2+(shake?Math.cos(performance.now()*.05)*shake*.5:0));ctx.scale(scale,scale);shake=Math.max(0,shake-dt*24);flash=Math.max(0,flash-dt);pulse=Math.max(0,pulse-dt);
 for(const r of RADII){ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.lineWidth=35;ctx.strokeStyle='#14283b';ctx.stroke();ctx.lineWidth=1;ctx.strokeStyle='#385d77';ctx.stroke();ctx.beginPath();ctx.arc(0,0,r+23,0,TAU);ctx.setLineDash([2,12]);ctx.strokeStyle='#244859';ctx.stroke();ctx.setLineDash([])}
 const t=engine?.time??0;ctx.save();ctx.rotate(-Math.PI/2);ctx.beginPath();ctx.arc(0,0,100,0,TAU);ctx.lineWidth=2;ctx.strokeStyle='#244253';ctx.stroke();if(engine){ctx.beginPath();ctx.arc(0,0,100,0,TAU*((engine.tournament||engine.level)?Math.max(0,1-t/engine.duration):engine.config.survival?1:Math.max(0,1-t/DURATION)));ctx.strokeStyle=t>90?'#ff8147':'#73e7f4';ctx.stroke()}ctx.restore();
 for(let i=0;i<48;i++){const a=i/48*TAU;ctx.beginPath();ctx.moveTo(Math.cos(a)*239,Math.sin(a)*239);ctx.lineTo(Math.cos(a)*(i%4===0?246:242),Math.sin(a)*(i%4===0?246:242));ctx.strokeStyle=i%4===0?'#4b718c':'#263e53';ctx.lineWidth=1;ctx.stroke()}
 const objects=engine?engine.active:[{type:'hazard',lane:1,angle:1.3},{type:'hazard',lane:0,angle:4.2},...Array.from({length:6},(_,i)=>({type:'energy',lane:1,angle:2.8+i*.16}))];
 for(const o of objects){if(o.done&&o.type!=='hazard')continue;if(o.type==='hazard'&&o.done)continue;const {x,y}=objectPosition(o);ctx.save();ctx.translate(x,y);ctx.rotate(o.angle-Math.PI/2);if(o.type==='hazard'){ctx.fillStyle=o.hit?'#55394b':o.wall?'#ff4b64':'#ff825a';ctx.fillRect(o.wall?-52:-14,-19,o.wall?104:28,38);ctx.fillStyle=o.hit?'#bba18c':'#352819';ctx.fillRect(-9,-12,2,24);ctx.fillRect(-2,-12,2,24);ctx.fillRect(5,-12,2,24);ctx.strokeStyle='#ffad71';ctx.lineWidth=1;ctx.strokeRect(o.wall?-52:-14,-19,o.wall?104:28,38)}else if(o.type==='shield'){ctx.rotate(-(o.angle-Math.PI/2));ctx.fillStyle='#8cdbef';ctx.fillRect(-8,-8,16,16);ctx.fillStyle='#10212c';ctx.fillRect(-5,-1,10,2);ctx.fillRect(-1,-5,2,10)}else{ctx.rotate(Math.PI/4);ctx.fillStyle='#c9ff65';const size=o.type==='gold'?7:4.5;if(o.type==='gold'){ctx.strokeStyle='#c9ff6580';ctx.lineWidth=1;ctx.strokeRect(-11,-11,22,22)}ctx.fillRect(-size,-size,size*2,size*2)}ctx.restore()}
 if(engine){const a=engine.travel-Math.PI/2,p={x:Math.cos(a)*engine.radius,y:Math.sin(a)*engine.radius};if(state==='playing'){trail.push({...p,life:.25});if(trail.length>40)trail.shift()}for(const tr of trail)tr.life-=dt;paintTrail(ctx,trail,save.trail,TRAILS.find(x=>x.id===save.trail)?.color||ballColor());trail=trail.filter(x=>x.life>0);ctx.globalAlpha=1;if(engine.invulnerableUntil>engine.time&&Math.floor(performance.now()/90)%2===0)ctx.globalAlpha=.4;ctx.shadowBlur=save.reduced?0:14;ctx.shadowColor=ballColor();ctx.fillStyle=ballColor();paintBall(ctx,p.x,p.y,7,BALLS.find(x=>x.id===save.ball)||BALLS[0],performance.now()/1000);ctx.shadowBlur=0;ctx.globalAlpha=1;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(a+Math.PI/2);ctx.strokeStyle='#ffffff80';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(2,0);ctx.stroke();ctx.restore()}else{paintBall(ctx,-206,0,7,BALLS.find(x=>x.id===save.ball)||BALLS[0],performance.now()/1000)}
 for(const p of particles){p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.03,dt);p.vy*=Math.pow(.03,dt);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size)}particles=particles.filter(x=>x.life>0);ctx.globalAlpha=1;if(pulse>0&&!save.reduced){ctx.strokeStyle=`rgba(229,237,120,${pulse*.35})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,230+(.35-pulse)*35,0,TAU);ctx.stroke()}ctx.restore();if(flash>0){ctx.fillStyle=`rgba(255,129,71,${flash*.65})`;ctx.fillRect(0,0,width,height)}
}
function frame(now){const dt=Math.min(.05,(now-previous)/1000||0);previous=now;if(state==='playing'){accumulator+=dt;while(accumulator>=1/120&&state==='playing'){engine.update(1/120);if(save.tournament&&!engine.ended&&engine.time>=engine.duration)engine.finish(true);events();accumulator-=1/120}sound.music();uiClock+=dt;if(uiClock>.05){uiClock=0;updateHUD()}}draw(dt);if(currentPage==='store')drawStorePreview();requestAnimationFrame(frame)}
$('start').addEventListener('click',start);$('retry').addEventListener('click',nextRun);$('back').addEventListener('click',goHome);$('flip').addEventListener('click',flip);canvas.addEventListener('pointerdown',e=>{if(e.button===0){e.preventDefault();if(state==='playing')flip()}});$('pause').addEventListener('click',()=>setPause(state!=='paused'));$('resume').addEventListener('click',()=>setPause(false));$('restart').addEventListener('click',goHome);
document.addEventListener('keydown',e=>{if(currentPage!=='play'||$('settings-dialog').open||(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement))return;if(['Space','ArrowLeft','ArrowRight','KeyA','KeyD'].includes(e.code)){if(e.repeat)return;if(e.target instanceof HTMLButtonElement&&e.code==='Space'&&!Object.keys(DIFFICULTIES).some(key=>e.target===$('difficulty-'+key)))return;e.preventDefault();if(state==='ready')start();else if(state==='ended')nextRun();else flip()}if((e.code==='KeyP'||e.code==='Escape')&&!e.repeat){e.preventDefault();if(state==='playing'||state==='paused')setPause(state==='playing')}});
$('sound').addEventListener('click',()=>{save.sound=!save.sound;sound.ensure();sound.volume();persist();refreshProfile()});$('settings').addEventListener('click',()=>{settingsPaused=state==='playing';if(settingsPaused)setPause(true);$('settings-dialog').showModal()});$('settings-dialog').addEventListener('close',()=>{if(settingsPaused&&state==='paused')setPause(false);settingsPaused=false});$('reduced').addEventListener('change',e=>{save.reduced=e.target.checked;document.documentElement.dataset.reduced=String(save.reduced);if(save.reduced){shake=0;flash=0;particles=[]}persist()});$('volume').addEventListener('input',e=>{save.volume=Number(e.target.value);sound.ensure();sound.volume();persist()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')setPause(true)});window.addEventListener('blur',()=>{if(state==='playing')setPause(true)});
for(const key of Object.keys(DIFFICULTIES))$('difficulty-'+key).addEventListener('click',()=>chooseDifficulty(key));
window.addEventListener('orbit-background',()=>{if(state==='playing')setPause(true)});
new ResizeObserver(resize).observe(canvas);refreshProfile();renderV5();renderLevels();requestAnimationFrame(frame);
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_orbit_run',title:'Read current orbit',description:'Read the visible run, personal record, and local progression.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return{state,run:engine?.snapshot()??null,difficulty:selectedDifficulty(),survivalBest:save.survivalBest,rampageBest:save.rampageBest,best:save.records[selectedDifficulty()],xp:save.xp,steroids:save.steroids,tournament:save.tournament,history:save.history}}});register({name:'start_orbit_run',title:'Start an orbit',description:'Start the selected mode: 120 seconds with warm-up, or an Extreme or impossible Rampage survival run from the start or results screen. Rejects while a run is active.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');if(state==='playing'||state==='paused')throw new Error('A run is already active');objectives=objectivesForMode();start();return{state,run:engine.snapshot()}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
